class QueryDecoder:
    """Answers decoding queries against the effective (approved and learned) theory."""

    def __init__(
        self,
        universe: WindowLayout,
        truths: Sequence[np.ndarray],
        active_clauses: Sequence[Sequence[int]],
    ) -> None:
        self.universe = universe
        length = int(universe.size)
        allowed = np.ones(length, dtype=bool)
        for clause in active_clauses:
            cover = np.zeros(length, dtype=bool)
            for pid in clause:
                cover |= truths[pid]
            allowed &= cover
        self.theory = allowed
        self._fixed_cache: dict[tuple[tuple[int, int], ...], np.ndarray] = {}
        self._summary_cache: dict[Any, tuple[np.ndarray, np.ndarray]] = {}
        self._range_cache: dict[tuple[int, str], list[tuple[int, int]]] = {}

    # ------------------------------------------------------------------ helpers
    def _fixed_key(self, fixed: Iterable[Mapping[str, Any]]) -> tuple[tuple[int, int], ...]:
        universe = self.universe
        bindings = []
        for binding in fixed:
            cell = universe.cell_of(binding["ref"])
            value = int(binding["value"])
            bindings.append((cell, universe.position_of_value(cell, value)))
        return tuple(sorted(bindings))

    def completions(self, fixed_key: tuple[tuple[int, int], ...]) -> np.ndarray:
        """Ascending universe indices satisfying the joint theory and the bindings."""
        cached = self._fixed_cache.get(fixed_key)
        if cached is None:
            mask = self.theory
            universe = self.universe
            for cell, position in fixed_key:
                mask = mask & (universe.positions[cell] == position)
            cached = np.flatnonzero(mask)
            if len(self._fixed_cache) >= _CACHE_LIMIT:
                self._fixed_cache.clear()
            self._fixed_cache[fixed_key] = cached
        return cached

    def summary(self, fixed_key: tuple[tuple[int, int], ...], cell: int) -> tuple[np.ndarray, np.ndarray]:
        """Per-value window counts (as prefix sums) and minimal universe index."""
        cached = self._summary_cache.get((fixed_key, cell))
        if cached is not None:
            return cached
        universe = self.universe
        domain_size = universe.cell_sizes[cell]
        indices = self.completions(fixed_key)
        totals = np.zeros(domain_size + 1, dtype=np.int64)
        smallest = np.full(domain_size, NO_WITNESS, dtype=np.int64)
        if indices.size:
            positions = universe.positions[cell][indices]
            counts = np.bincount(positions, minlength=domain_size)
            np.cumsum(counts, out=totals[1:])
            seen, first = np.unique(positions, return_index=True)
            smallest[seen] = indices[first]
        cached = (totals, smallest)
        if len(self._summary_cache) >= _CACHE_LIMIT:
            self._summary_cache.clear()
        self._summary_cache[(fixed_key, cell)] = cached
        return cached

    def ranges(self, field: int, prefix: str) -> list[tuple[int, int]]:
        key = (field, prefix)
        cached = self._range_cache.get(key)
        if cached is None:
            cached = prefix_intervals(self.universe.field_domains[field], prefix)
            self._range_cache[key] = cached
        return cached

    @staticmethod
    def _count(totals: np.ndarray, intervals: Sequence[tuple[int, int]]) -> int:
        total = 0
        for low, high in intervals:
            total += int(totals[high] - totals[low])
        return total

    @staticmethod
    def _witness(smallest: np.ndarray, intervals: Sequence[tuple[int, int]]) -> int | None:
        best = int(NO_WITNESS)
        for low, high in intervals:
            candidate = int(smallest[low:high].min())
            if candidate < best:
                best = candidate
        return None if best >= int(NO_WITNESS) else best

    # ------------------------------------------------------------------ answers
    def answer(self, query: Mapping[str, Any]) -> dict[str, Any]:
        universe = self.universe
        cell = universe.cell_of(query["target"])
        field = universe.field_of_cell(cell)
        prefix = str(query["prefix"])
        fixed_key = self._fixed_key(query.get("fixed") or [])
        totals, smallest = self.summary(fixed_key, cell)

        intervals = self.ranges(field, prefix)
        count = self._count(totals, intervals)
        witness = self._witness(smallest, intervals) if intervals else None

        tokens: list[str] = []
        for digit in DIGITS:
            extended = self.ranges(field, prefix + digit)
            if extended and self._count(totals, extended):
                tokens.append(digit)
        exact = exact_interval(universe.field_domains[field], prefix)
        if exact is not None and int(totals[exact[1]] - totals[exact[0]]):
            tokens.append(END_TOKEN)
        return {"count": int(count), "tokens": tokens, "witness": witness}


def decode_queries(
    universe: Any,
    truths: Sequence[np.ndarray],
    active_clauses: Sequence[Sequence[int]],
    queries: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Answer every decoding query in input order."""
    if not queries:
        return []
    decoder = QueryDecoder(universe, truths, active_clauses)
    return [decoder.answer(query) for query in queries]
